function ufFind(uf, x){
  x=String(x); ufAdd(uf,x);
  var root=x; while(uf.parent[root]!==root){ root=uf.parent[root]; }
  var cur=x;
  while(uf.parent[cur]!==root){ var nxt=uf.parent[cur]; uf.parent[cur]=root; cur=nxt; }
  return root;
}
function ufUnion(uf, a, b){
  a=String(a); b=String(b); ufAdd(uf,a); ufAdd(uf,b);
  var ra=ufFind(uf,a), rb=ufFind(uf,b);
  if(ra===rb) return;
  if(uf.rank[ra]<uf.rank[rb]){ uf.parent[ra]=rb; }
  else if(uf.rank[ra]>uf.rank[rb]){ uf.parent[rb]=ra; }
  else { uf.parent[rb]=ra; uf.rank[ra]++; }
}
function ufConnected(uf, a, b){ return ufFind(uf,a)===ufFind(uf,b); }
function ufCount(uf){
  var sets={}; for(var k in uf.parent){ sets[ufFind(uf,k)]=1; }
  return Object.keys(sets).length;
}
